def suffix_array(s):
    n = len(s)
    suffixes = [(s[i:], i) for i in range(n)]
    suffixes.sort(key=lambda x: x[0])
    return [i for _, i in suffixes]  # O(n^2 log n)

def lcp_array(s, sa):
    n = len(s)
    rank = [0] * n
    for i, idx in enumerate(sa):
        rank[idx] = i

    lcp = [0] * n
    k = 0
    for i in range(n):
        if rank[i] == 0:
            k = 0
            continue
        j = sa[rank[i] - 1]
        while i + k < n and j + k < n and s[i+k] == s[j+k]:
            k += 1
        lcp[rank[i]] = k
        if k > 0:
            k -= 1

    return lcp  # O(n)

def longest_repeated_substring(s):
    sa = suffix_array(s)
    lcp = lcp_array(s, sa)

    max_lcp = max(lcp)
    idx = lcp.index(max_lcp)

    return s[sa[idx]:sa[idx]+max_lcp]  # O(n log n)
